INSERT INTO public.source (id, title, source_type, author, edition, url, note)
SELECT id, title, source_type, author, edition, url, note FROM jsonb_populate_recordset(NULL::public.source, '[{"title": "宋史·卷441·徐铉传", "source_type": "primary", "author": "脱脱等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/1df54f287032ffe638308d6b8b6efe6b4bf86b76/content/books/zizhi-tongjian/vol-291/year-0953/part-05/sources/library/songshi-441-xuxuan-shuzhou/source.txt", "note": "《宋史》卷441·徐铉传，段落 songshi-9c6e46fee832-p071730；已核上下文及传主，纸本及异文待核。", "id": "84d8f35a-6bf4-5148-b357-052fd93ebcf8"}, {"title": "资治通鉴·卷291·广顺三年末至显德元年初及年界", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/1df54f287032ffe638308d6b8b6efe6b4bf86b76/content/books/zizhi-tongjian/vol-291/year-0953/part-05/sources/library/tongjian-291-953-end-954-opening/source.txt", "note": "《资治通鉴》卷291·广顺三年末至显德元年初及年界，段落 zizhi-tongjian-a63549944a71-p003459；已核上下文及传主，纸本及异文待核。", "id": "9578cbb6-a420-59ef-b7b1-f00bdac11d46"}, {"title": "新五代史·卷50·杂传第三十八·王殷", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/1df54f287032ffe638308d6b8b6efe6b4bf86b76/content/books/zizhi-tongjian/vol-291/year-0953/part-05/sources/library/xinwudaishi-50-wangyin-death/source.txt", "note": "《新五代史》卷50·杂传第三十八·王殷，段落 xin-wudaishi-b08f244b9241-p001944；已核上下文及传主，纸本及异文待核。", "id": "28024251-56a8-5552-8873-7ddcbc11f41f"}, {"title": "资治通鉴·卷291·广顺三年六月至十二月", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/a03e158968cf63490b7ea1d52bdaea928e33b44d/content/books/zizhi-tongjian/vol-291/year-0953/part-03/sources/library/tongjian-291-953-june-december/source.txt", "note": "《资治通鉴》卷291·广顺三年六月至十二月，段落 zizhi-tongjian-a63549944a71-p003458；已核上下文及传主，纸本及异文待核。", "id": "ef9b7b67-6d1a-52f9-b2db-fffd976d2c68"}, {"title": "旧五代史·卷113·太祖本纪四·广顺三年十二月", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/cfe4b4148ad7d1e2ee8fc2e5d5c0cfad4d17a33c/content/books/zizhi-tongjian/vol-291/year-0953/part-04/sources/library/jiuwudaishi-113-december-953/source.txt", "note": "《旧五代史》卷113·太祖本纪四·广顺三年十二月，段落 jiu-wudaishi-205deb4a7860-p002695；已核上下文及传主，纸本及异文待核。", "id": "b020b38e-e129-5fc3-9a1e-c8c9391c12fc"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "王殷（后汉后周将）", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "瀛州籍将领。950年以侍卫步军都指挥使身份奉命驻澶州防备契丹，后来参与后周建国。《旧五代史》记他自称出生在魏州开元寺，籍贯与出生地分开。与晚唐后梁同名王殷分开建档，生卒年本批未录。", "biography": null, "status": "draft", "id": "4b85115a-7337-546f-af4c-9f6bd20f13c6"}, {"name": "郭威", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷272同光元年条所见人物：郭威。", "biography": null, "status": "draft", "id": "3fe84db3-aa25-5be9-9dd3-8b46e28213af"}, {"name": "郑仁诲", "aliases": ["鄭仁誨"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "晋阳人，后周内客省使、恩州团练使。952年三月任枢密副使，新旧五代史同日记载。生卒年尚未录入。", "biography": null, "status": "draft", "id": "f7eb66ac-1c5c-5720-aa2e-9256e75c2b71"}, {"name": "徐铉", "aliases": ["徐鉉"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "字鼎臣，南唐官员。947年与韩熙载上疏请求处死陈觉、冯延鲁，李璟未采纳。《资治通鉴》此处记会稽，《宋史》记扬州广陵人，籍贯差异保留。生卒年尚未录入。", "biography": null, "status": "draft", "id": "aa3f495d-5349-5093-bee4-984f876430c1"}, {"name": "田敬洙", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南唐楚州刺史。建议修白水塘灌田充实边地，冯延巳赞成。相关工程后来引发侵扰夺田，白水塘最终未建成。生卒年未载。", "biography": null, "status": "draft", "id": "41c6bbb7-6336-5592-9e4a-672de8be217c"}, {"name": "冯延巳", "aliases": ["馮延巳", "冯延己", "馮延己", "冯延已"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南唐官员，曾任驾部郎中、齐王元帅府常书记。《资治通鉴》本段作冯延己及延已，《新五代史》作冯延巳；据同一南唐政局、陈觉及常梦锡等对应关系校核为同人，展示采用冯延巳，原文异体保留。生卒年尚未核。", "biography": null, "status": "draft", "id": "0b3ed4d7-1a4c-50a5-ad65-aee4b82089ba"}, {"name": "李德明", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南唐尚书员外郎。949年条下与钟谟一起参与国政，史书记两人受李璟宠信，但不是魏岑的同党。生卒年尚未录入。", "biography": null, "status": "draft", "id": "3aa99691-05a6-5807-a0c3-f56c9cebb4f1"}, {"name": "李璟", "aliases": ["徐景通", "景通", "李景"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷272同光元年条所见人物：李璟。", "biography": null, "status": "draft", "id": "6bf72971-88c3-5187-8f25-98cde2a9554a"}, {"name": "冯延鲁", "aliases": ["馮延魯"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "冯延巳的弟弟，南唐官员，曾任东都判官、礼部员外郎，与兄长同在元帅府。曾请求允许百姓卖子女；李昪去世后又参与起草包含这一规定的遗诏。生卒年尚未核。", "biography": null, "status": "draft", "id": "a589c28e-c0c5-58bf-989f-96457604ccdd"}, {"name": "徐锴", "aliases": ["徐鍇"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "徐铉之弟，南唐右拾遗。953年上表反对由冯延鲁巡抚各州，李璟将他贬为校书郎、分司东都。生卒年未载。", "biography": null, "status": "draft", "id": "e3381963-adff-5c03-b280-7c4195c5b1c5"}, {"name": "盘崇", "aliases": ["盤崇"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "道州盘容洞地方首领。953年末条下记其聚众自称盘容州都统，多次进犯郴州、道州。具体族属不按现代民族强定，不与南汉将潘崇彻混同，生卒年未载。", "biography": null, "status": "draft", "id": "6efd53a8-85c5-5520-a410-58febd8ea7ec"}, {"name": "柴荣", "aliases": ["郭荣", "柴榮", "郭榮"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本姓柴，950年《资治通鉴》以郭荣记名，任贵州刺史、天雄牙内都指挥使。父亲柴守礼是郭威妻子柴氏的兄长，郭威在尚无儿子时收养他。《新五代史》记他幼年跟随姑母在郭威家成长。《旧五代史》的任职纪年与通鉴不同，分别保留。", "biography": null, "status": "draft", "id": "697c1a4f-b373-5a78-8b47-330fe349a424"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "王殷常带数百随从出入，又请求拨给铠甲兵器用于巡逻，郭威犹豫", "start_year": 953, "end_year": 953, "time_original": "953年十二月王殷留京任巡检后", "dynasty": "五代十国", "description": "王殷常带数百随从出入，又请求拨给铠甲兵器用于巡逻，郭威犹豫。", "phases": [], "location_name": "后周京城", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "c4d7ac2b-bd9e-5b4a-b14d-a1ae3a9c63ef"}, {"title": "郭威抱病到滋德殿，王殷入宫问安时被拘捕", "start_year": 953, "end_year": 953, "time_original": "953年十二月壬申，《通鉴》纪日", "dynasty": "五代十国", "description": "郭威抱病到滋德殿，王殷入宫问安时被拘捕。", "phases": [], "location_name": "滋德殿", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "06b4abb5-a301-5cc8-a280-bf4ac19d4e1b"}, {"title": "郭威下制诬称王殷计划在郊祀日作乱，将他流放登州", "start_year": 953, "end_year": 953, "time_original": "953年十二月壬申被捕以后", "dynasty": "五代十国", "description": "郭威下制诬称王殷计划在郊祀日作乱，将他流放登州。", "phases": [], "location_name": "后周京城至登州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "ac657280-193f-51df-9cab-b8e190a330ff"}, {"title": "王殷被押出城后遭杀害", "start_year": 953, "end_year": 953, "time_original": "953年十二月被捕、流放制书下达以后", "dynasty": "五代十国", "description": "王殷被押出城后遭杀害。", "phases": [], "location_name": "后周京城城外", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "4af993db-0a59-5744-a517-0c1f08e44101"}, {"title": "郭威命郑仁诲到邺都安抚", "start_year": 953, "end_year": 953, "time_origi